def loan_signed_stats(
    *, principal: int, months: int, insured: bool, discount: float, open_loans: int
) -> StatDelta:
    """Estadísticas de quien firma un préstamo.

    Args:
        discount: Lo que su tipo baja del de un cliente nuevo (Euríbor + diferencial).
        open_loans: Préstamos abiertos que tiene contando este.
    """
    delta = StatDelta(
        add={"loans_signed": 1},
        peak={"loan_principal_max": principal, "loans_open_max": open_loans},
    )
    for stat, hit in (
        ("loan_longest", months == max(LOAN_TERMS)),
        ("loan_insured", insured),
        ("loan_preferred", discount >= LOAN_PREFERRED - 1e-9),
    ):
        if hit:
            delta.add[stat] = 1
    return delta


def financed_stats(
    *,
    plan: str,
    amount: int,
    grace: bool,
    works: bool,
    coffee: bool,
    could_pay: bool,
    open_count: int,
    ipc: int,
    trap: bool,
) -> StatDelta:
    """Estadísticas de quien financia una compra (💳 Financiar).

    Args:
        plan: `normal`, `cero` (0 % TIN) o `plazos` (Paga en 3).
        coffee: Si es un café de la pala.
        could_pay: Si tenía para pagarlo al contado.
        open_count: Compras financiadas sin terminar de pagar, contando esta.
        ipc: El IPC del crédito al firmar, en %.
        trap: Si es el 0 % en el plazo más corto (peor TAE que el normal).
    """
    delta = StatDelta(
        add={"financed": 1},
        peak={"financed_max": amount, "financed_open_max": open_count},
    )
    for stat, hit in (
        ("financed_bnpl", plan == "plazos"),
        ("financed_coffee", coffee and plan == "plazos"),
        ("financed_zero", plan == "cero"),
        ("financed_trap", trap),
        ("financed_grace", grace),
        ("financed_works", works),
        ("financed_could_pay", could_pay),
        ("financed_high_ipc", ipc >= IPC_CAP // 2),
    ):
        if hit:
            delta.add[stat] = 1
    return delta


def business_loan_signed_stats(
    *, principal: int, months: int, corporate: bool, open_loans: int
) -> StatDelta:
    """Estadísticas de quien firma un préstamo a nombre de su negocio (🏪 Negocio).

    Args:
        corporate: Si lo firma su sociedad.
        open_loans: Préstamos vivos del negocio contando este.
    """
    delta = StatDelta(
        add={"biz_loans_signed": 1},
        peak={"biz_loan_principal_max": principal, "biz_loans_open_max": open_loans},
    )
    if corporate:
        delta.add["biz_loan_company"] = 1
    if months == max(LOAN_TERMS):
        delta.add["biz_loan_longest"] = 1
    return delta


def business_loan_closed_stats() -> StatDelta:
    """Estadísticas de quien amortiza antes de tiempo un préstamo de su negocio."""
    return StatDelta(add={"biz_loans_repaid_early": 1})


def business_loan_night_stats(events: Iterable[str]) -> dict[str, int]:
    """Lo que suman las cuotas de una noche de un negocio (`NightRun.loans`)."""
    events = list(events)
    counts = {
        "biz_loan_installments": events.count("pagada") + events.count("devuelto"),
        "biz_loan_unpaid": events.count("sin_pagar"),
        "biz_loans_finished": events.count("devuelto"),
        "biz_loan_defaults": events.count("vencido"),
    }
    return {stat: n for stat, n in counts.items() if n}


def loan_closed_stats(*, status: str) -> StatDelta:
    """Estadísticas de quien cierra un préstamo a mano: amortizado (`pagado`) o desistido."""
    return StatDelta(add={"loans_repaid_early" if status == "pagado" else "loans_desisted": 1})


def loan_night_stats(*, finished: int, covered: int, unpaid: int, defaulted: int) -> StatDelta:
    """Estadísticas de los préstamos de un miembro en el cierre de una noche de `pisos`."""
    delta = StatDelta()
    for stat, count in (
        ("loans_finished", finished),
        ("loan_covered", covered),
        ("loan_unpaid", unpaid),
        ("loan_defaults", defaulted),
    ):
        if count:
            delta.add[stat] = count
    return delta


def remortgage_signed_stats(
    *, principal: int, months: int, room: int, habitual: bool, dwelling: bool, open_count: int
) -> StatDelta:
    """Estadísticas de quien firma una rehipoteca (`banco`, 🔐 Garantías).

    Args:
        room: Lo más que le prestaba la tasación (pedirlo entero es «hasta el último ladrillo»).
        habitual: Si es la casa en la que vive.
        dwelling: Si es vivienda (si no, un local, un garaje, un trastero…).
        open_count: Rehipotecas que tiene abiertas contando esta.
    """
    delta = StatDelta(
        add={"remortgages_signed": 1},
        peak={"remortgage_principal_max": principal, "remortgages_open_max": open_count},
    )
    for stat, hit in (
        ("remortgage_home", habitual),
        ("remortgage_not_home", not dwelling),
        ("remortgage_shortest", months == min(REMORTGAGE_TERMS)),
        ("remortgage_full", principal >= room),
        ("remortgage_minimum", principal == REMORTGAGE_MIN),
    ):
        if hit:
            delta.add[stat] = 1
    return delta


def guarantee_signed_stats(*, given: bool, open_count: int = 0) -> StatDelta:
    """Estadísticas de un aval firmado: de quien avala (`given`) o de quien recibe el aval.

    Args:
        open_count: Avales vivos de quien avala, contando este.
    """
    if not given:
        return StatDelta(add={"guarantees_received": 1})
    return StatDelta(add={"guarantees_given": 1}, peak={"guarantees_open_max": open_count})


def guarantee_refused_stats() -> StatDelta:
    """Estadísticas de quien dice que no a una petición de aval."""
    return StatDelta(add={"guarantee_refused": 1})


def guarantee_night_stats(
    *, claimed: int = 0, defaulted: int = 0, repaid: int = 0, recovered: int = 0
) -> StatDelta:
    """Estadísticas de los avales de un miembro en el cierre de una noche de `pisos`.

    Args:
        claimed: Lo que el banco le reclama hoy como avalista.
        defaulted: Lo que el banco reclama hoy a su avalista por él.
        repaid: Lo que hoy ha devuelto a su avalista.
        recovered: Lo que hoy le ha devuelto su avalado.
    """
    delta = StatDelta()
    for stat, amount in (
        ("guarantee_claimed", claimed),
        ("guarantee_defaulted", defaulted),
        ("guarantee_repaid", repaid),
        ("guarantee_recovered", recovered),
    ):
        if amount:
            delta.add[stat] = 1 if stat in ("guarantee_claimed", "guarantee_defaulted") else amount
    return delta


def advance_signed_stats(*, principal: int, months: int, open_count: int) -> StatDelta:
    """Estadísticas de quien firma un anticipo de rentas (`banco`, 💸 Anticipos).

    Args:
        principal: Lo que adelanta el banco.
        months: Meses de renta adelantados.
        open_count: Anticipos vivos que tiene contando este (uno por inmueble).
    """
    delta = StatDelta(
        add={"advances_signed": 1},
        peak={"advance_principal_max": principal, "advances_open_max": open_count},
    )
    if months == max(ADVANCE_TERMS):
        delta.add["advance_longest"] = 1
    if months == min(ADVANCE_TERMS):
        delta.add["advance_shortest"] = 1
    return delta


def advance_closed_stats(*, status: str) -> StatDelta:
    """Estadísticas de quien cierra un anticipo a mano: cancelado (`pagado`) o desistido."""
    return StatDelta(add={"advance_repaid" if status == "pagado" else "advance_desisted": 1})


def advance_orphan_stats() -> StatDelta:
    """Estadísticas de quien paga una cuota del anticipo sin inquilino que pague (la noche)."""
    return StatDelta(add={"advance_orphan": 1})


def remortgage_executed_stats() -> StatDelta:
    """Estadísticas de quien pierde en una ejecución un inmueble que había rehipotecado."""
    return StatDelta(add={"remortgage_executed": 1})


def bank_panel_stats(*, asnef: bool = False, books: bool = False) -> StatDelta:
    """Estadísticas de quien abre `banco` (en el fichero de morosos) o mira las cuentas."""
    delta = StatDelta()
    if asnef:
        delta.add["asnef_seen"] = 1
    if books:
        delta.add["bank_books"] = 1
    return delta


def _sunday(when: datetime) -> dict[str, int]:
    """El Rastro de verdad es los domingos: cualquier jugada ese día cuenta."""
    return {"market_sunday": 1} if when.weekday() == 6 else {}


def market_listing_stats(*, when: datetime) -> StatDelta:
    """Estadísticas de quien pone algo en un puesto del Rastro."""
    return StatDelta(add={"market_listings": 1, **_sunday(when)})


def market_offer_stats() -> StatDelta:
    """Estadísticas de quien publica una oferta de venta directa a un miembro."""
    return StatDelta(add={"market_offers": 1})


def market_withdraw_stats() -> StatDelta:
    """Estadísticas de quien retira un puesto sin pujas."""
    return StatDelta(add={"market_withdrawn": 1})


def market_expired_stats() -> StatDelta:
    """Estadísticas de quien ve cerrar su puesto sin una sola puja."""
    return StatDelta(add={"market_expired": 1})


def market_bid_stats(*, amount: int, when: datetime) -> StatDelta:
    """Estadísticas de quien puja."""
    return StatDelta(add={"market_bids": 1, **_sunday(when)}, peak={"market_bid_max": amount})


def market_outbid_stats() -> StatDelta:
    """Estadísticas de quien es superado en una subasta."""
    return StatDelta(add={"market_outbid": 1})


def housing_panel_stats(
    *,
    screen: str,
    level: str | None = None,
    squatters: bool = False,
    building: str | None = None,
) -> StatDelta:
    """Estadísticas de usar el panel de `pisos`.

    Args:
        screen: `abrir` (el comando), `renta` (cambiar la renta que se pide),
            `desahucio` (pedirlo), `atajo` (el botón 👥 Candidatos) o una pantalla (solo
            cuenta `candidatos`, `calles` y `edificio`).
        level: La renta elegida, con `renta`.
        squatters: Si el desahucio es de okupas.
        building: La clave del edificio que se ve, con `edificio`.
    """
    add: dict[str, int] = {}
    if screen == "abrir":
        add["pisos_opened"] = 1
    elif screen == "renta":
        add["pisos_level_changes"] = 1
        if level:
            add[f"{PISOS_LEVEL_PREFIX}{level}"] = 1
    elif screen == "desahucio":
        add["pisos_evictions"] = 1
        if squatters:
            add["pisos_squatters_evicted"] = 1
    elif screen == "candidatos":
        add["pisos_candidates_seen"] = 1
    elif screen == "atajo":
        add["pisos_shortcut"] = 1
    elif screen == "calles":
        add["pisos_streets_opened"] = 1
    elif screen == "edificio" and building:
        add[f"{PISOS_BUILDING_PREFIX}{building}"] = 1
    return StatDelta(add=add)


def _unit_kind(key: str) -> str:
    item = STREET_UNIT_BY_KEY.get(key) or LISTING_BY_KEY.get(key)
    return item.kind if item is not None else ""


def housing_streets_stats(shares: Mapping[str, int]) -> StatDelta:
    """Lo que tiene un miembro en los edificios de las calles de `pisos`, como máximos.

    Args:
        shares: Sus participaciones por inmueble (una planta o una habitación, con su clave).
    """
    whole = {key for key, n in shares.items() if n >= HOUSING_SHARES}
    held: dict[str, set[str]] = {}  # edificio -> unidades en que tiene algo
    for key in shares:
        if (found := building_of(key)) is not None:
            held.setdefault(found.key, set()).add(key.split("~")[0])
    streets: dict[str, set[str]] = {}
    for key in held:
        b = STREET_BUILDING_BY_KEY[key]
        streets.setdefault(b.barrio, set()).add(b.street)
    new_units = {key.split("~")[0] for key in shares} & STREET_UNIT_BY_KEY.keys()
    peak = {
        "pisos_street_units_max": len(new_units),
        "pisos_buildings_max": len(held),
        "pisos_streets_barrio_max": max(map(len, streets.values()), default=0),
        "pisos_penthouses_max": sum(1 for key in shares if is_penthouse(key.split("~")[0])),
    }
    for key, units in held.items():
        b = STREET_BUILDING_BY_KEY[key]
        kinds = {_unit_kind(k) for k in units}
        complete = all(u.key in whole for u in b.units)
        whole_kinds = {(_unit_kind(u.key), u.level) for u in b.units if u.key in whole}
        cellar = [u for u in b.units if u.level == -1]
        for stat, hit in (
            ("pisos_pack", bool(kinds & STREET_HOMES) and {"garaje", "trastero"} <= kinds),
            ("pisos_whole_bloque", complete and b.kind == BLOQUE and len(b.units) >= 6),
            ("pisos_whole_guardamuebles", complete and b.kind == GUARDAMUEBLES),
            ("pisos_whole_aparcamiento", complete and b.kind == APARCAMIENTO),
            ("pisos_whole_pantalan", complete and b.kind == PANTALAN),
            (
                "pisos_attic_basement",
                b.kind == BLOQUE
                and bool(cellar)
                and all(u.key in whole for u in cellar)
                and any(kind == "atico" for kind, _level in whole_kinds),
            ),
            (
                "pisos_above_shop",
                b.kind == BLOQUE
                and ("local", 0) in whole_kinds
                and any(kind in STREET_HOMES and level > 0 for kind, level in whole_kinds),
            ),
        ):
            if hit:
                peak[stat] = 1
    return StatDelta(peak=peak)


def housing_purchase_stats(
    *,
    kind: str,
    barrio: str,
    total: int,
    itp: int,
    shares: int,
    shares_now: int,
    holdings: int,
    whole: int,
    islands: int,
    balance_after: int,
    when: datetime,
    tensed: bool = False,
    barrio_whole: bool = False,
) -> StatDelta:
    """Estadísticas de una compra en `pisos`.

    Args:
        kind: Tipo de inmueble.
        barrio: Clave del barrio.
        total: Todo lo pagado (precio, ITP y notaría).
        itp: ITP pagado.
        shares: Participaciones compradas.
        shares_now: Las que tiene ahora en ese inmueble.
        holdings: Inmuebles en los que tiene algo.
        whole: Inmuebles que tiene enteros.
        islands: Islas en las que tiene algo.
        balance_after: Saldo tras pagar.
        tensed: Si con esta compra el barrio ha pasado a zona tensionada.
        barrio_whole: Si ahora tiene enteros todos los inmuebles del catálogo del barrio.
    """
    add = {
        "pisos_bought": 1,
        "pisos_spent": total,
        "pisos_itp": itp,
        f"{PISOS_KIND_PREFIX}{kind}": 1,
        f"{PISOS_BARRIO_PREFIX}{barrio}": 1,
    }
    for stat, hit in (
        ("pisos_one_share", shares == 1),
        ("pisos_whole_buy", shares_now == 100),
        ("pisos_night", 0 <= when.hour < 6),
        ("pisos_canarias_day", (when.month, when.day) == (5, 30)),
        ("pisos_broke", balance_after < PISOS_BROKE_BELOW),
        ("pisos_tensed", tensed),
        ("pisos_barrio_whole", barrio_whole),
    ):
        if hit:
            add[stat] = 1
    return StatDelta(
        add=add,
        peak={
            "pisos_buy_max": total,
            "pisos_holdings_max": holdings,
            "pisos_whole_max": whole,
            "pisos_islands_max": islands,
        },
    )


def housing_sale_stats(
    *,
    shares: int,
    received: int,
    gain: int,
    arrears: int,
    held_days: int,
    holdings_left: int,
    floor: bool = False,
) -> StatDelta:
    """Estadísticas de una venta en `pisos`.

    Args:
        shares: Participaciones vendidas.
        received: Lo que cobró.
        gain: Ganancia patrimonial (negativa si perdió).
        arrears: Deudas del piso que se le descontaron.
        held_days: Días desde que compró.
        holdings_left: Inmuebles en los que le queda algo.
        floor: Si lo vendido es una planta de un inmueble dividido.
    """
    add = {"pisos_sold": 1, "pisos_sold_y": received}
    for stat, hit in (
        ("pisos_floor_sold", floor),
        ("pisos_exit", holdings_left == 0),
        ("pisos_sold_whole", shares == 100),
        ("pisos_flip", held_days == 0),
        ("pisos_loss", gain < 0),
        ("pisos_arrears_paid", arrears > 0),
    ):
        if hit:
            add[stat] = 1
    return StatDelta(add=add, peak={"pisos_gain_max": max(0, gain)})


def housing_tax_stats(*, taxes: dict[str, int], rent: int) -> StatDelta:
    """Estadísticas de lo que lleva pagado un miembro por sus pisos (máximos, no sumas).

    Args:
        taxes: Su desglose de `EconomyService.housing_tax_breakdown` (desde siempre).
        rent: Toda la renta que ha cobrado (su estadística `pisos_rent`).
    """
    total = sum(taxes.values())
    peak = {
        "pisos_tax_total": total,
        "pisos_tax_alquiler": taxes.get("alquiler", 0),
        "pisos_tax_ganancia": taxes.get("ganancia", 0),
    }
    add = {"pisos_tax_over_rent": 1} if rent > 0 and total > rent else {}
    return StatDelta(add=add, peak={k: v for k, v in peak.items() if v > 0})


#: Acciones de las fases 2 a 4 y el contador que suma cada una (`housing_action_stats`).
HOUSING_ACTIONS = {
    "amortiza": "pisos_amortized",
    "vpo_signup": "pisos_vpo_signups",
    "compra_vpo": "pisos_vpo_bought",
    "devuelve_vpo": "pisos_vpo_returned",
    "se_muda": "pisos_home",
    "casero_miembro": "pisos_member_landlord",
    "inquilino_miembro": "pisos_member_tenant",
    "licencia": "pisos_licenses",
    "venta_fondo": "pisos_vulture_sold",
    "socimi": "pisos_socimi",
    "elige_inquilino": "pisos_pick_self",
    "firma_candidato": "pisos_chosen",
    "descarta": "pisos_discarded",
    "seguro": "pisos_insured",
    "desahucio": "pisos_lawyer",
    "subasta": "pisos_auctions",
    "puja": "pisos_bids",
    "superado": "pisos_outbid",
    "gana_subasta": "pisos_auctions_won",
    "subasta_desierta": "pisos_auction_deserted",
    "vende_miembro": "pisos_sold_member",
    "compra_miembro": "pisos_bought_member",
    "reforma": "pisos_reforms",
    "decide": "pisos_decisions",
    "licencia_denegada": "pisos_license_denied",
    "propone": "pisos_proposals",
    "vota": "pisos_votes",
    "junta_aprobada": "pisos_motions_won",
    "junta_rechazada": "pisos_motions_lost",
    "administra": "pisos_admin",
    "derrama_fondo": "pisos_levies",
    "division": "pisos_divisions",
    "plantas": "pisos_floor_splits",
    "habitaciones": "pisos_room_splits",
    "juntar": "pisos_rooms_joined",
}


def housing_action_stats(
    action: str,
    *,
    loan: int = 0,
    floor: bool = False,
    ceiling: bool = False,
    aval: bool = False,
    effort: float | None = None,
    guarantee: bool = False,
    tenant: str | None = None,
    risk: str | None = None,
    young: bool = False,
    fee: int = 0,
    amount: int = 0,
    judicial: bool = False,
    extended: bool = False,
    gift: bool = False,
    preference: bool = False,
    reference: bool = False,
    moved_in: bool = False,
    overpaid: bool = False,
    reform: str = "",
    rehab: bool = False,
    choice: str = "",
    silent: bool = False,
    units: int = 0,
    mortgaged: bool = False,
    rushed: bool = False,
    floor_unit: bool = False,
) -> StatDelta:
    """Estadísticas de una acción de las fases 2 a 6 (`HOUSING_ACTIONS`, o `hipoteca`).

    Args:
        loan: Lo prestado, con `hipoteca`.
        floor: Con `hipoteca`, si se firmó con el Euríbor en el mínimo (0 %).
        ceiling: Con `hipoteca`, si se firmó con el Euríbor en el máximo (5 %).
        aval: Con `hipoteca`, si solo se dio con el aval de los padres; con
            `inquilino_miembro`, si el aval le libró de la garantía adicional.
        effort: Con `inquilino_miembro`, la parte del sueldo que se lleva la renta
            (`housing.effort`; `None` sin nómina).
        guarantee: Con `inquilino_miembro`, si dejó la garantía adicional.
        tenant: Con `firma_candidato`, el inquilino.
        risk: Con `firma_candidato`, su riesgo de impago (`bajo`, `medio`, `alto`).
        young: Con `firma_candidato`, si el contrato tiene la reducción del 70 %.
        fee: Con `desahucio`, lo pagado en abogado y procurador (0 si lo pagó el seguro).
        amount: Con `gana_subasta`, lo pagado.
        judicial: Con `gana_subasta`, si era una subasta judicial.
        extended: Con `puja`, si alargó la subasta (última hora).
        gift: Con `vende_miembro`, si vendió por debajo del valor.
        preference: Con `compra_miembro`, si compró con su derecho preferente.
        reference: Con `compra_miembro`, si el ITP fue sobre el valor de referencia.
        moved_in: Con `compra_miembro`, si era su piso de alquiler y ahora vive en lo suyo.
        overpaid: Con `compra_miembro`, si pagó más de un 20 % sobre el valor.
        reform: Con `reforma`, cuál (`amount`, lo que costó con impuestos).
        rehab: Con `reforma`, si cuenta como rehabilitación.
        silent: Con `junta_aprobada`, si nadie más votó (el silencio vale como sí).
        units: Con `plantas` o `habitaciones`, cuántas salen (`amount`, lo que costó con
            impuestos).
        mortgaged: Con `plantas`, si quien divide lo tiene hipotecado.
        rushed: Con `juntar`, si alguna habitación aún se estaba amueblando.
        floor_unit: Con `vende_miembro`, si vende una planta de un inmueble dividido.
        choice: Con `decide`, la forma elegida (no cuenta nada más: los logros de cada forma
            salen al resolverse, con el cierre de la noche).
    """
    if action == "desahucio":
        return StatDelta(add={"pisos_lawyer": fee} if fee else {"pisos_lawyer_free": 1})
    if action == "hipoteca":
        add = {"pisos_mortgages": 1}
        for stat, hit in (
            ("pisos_mortgage_floor", floor),
            ("pisos_mortgage_ceiling", ceiling),
            ("pisos_aval_mortgage", aval),
        ):
            if hit:
                add[stat] = 1
        return StatDelta(add=add, peak={"pisos_loan_max": loan})
    stat = HOUSING_ACTIONS.get(action)
    if stat is None:
        return StatDelta()
    delta = StatDelta(add={stat: 1})
    if action == "inquilino_miembro":
        if effort is not None:
            overburden = effort > HOUSING_OVERBURDEN
            delta.add["pisos_overburden" if overburden else "pisos_unicorn"] = 1
            delta.peak["pisos_effort_peak"] = round(effort * 100)
        if guarantee:
            delta.add["pisos_guarantee"] = 1
        if aval:
            delta.add["pisos_aval_rent"] = 1
    for stat, hit in (
        ("pisos_snipe", action == "puja" and extended),
        ("pisos_judicial_won", action == "gana_subasta" and judicial),
        ("pisos_member_gift", action == "vende_miembro" and gift),
        ("pisos_preference", action == "compra_miembro" and preference),
        ("pisos_member_reference", action == "compra_miembro" and reference),
        ("pisos_moved_in", action == "compra_miembro" and moved_in),
        ("pisos_member_overpaid", action == "compra_miembro" and overpaid),
        ("pisos_split_mortgaged", action == "plantas" and mortgaged),
        ("pisos_rooms_rushed", action == "juntar" and rushed),
        ("pisos_floor_sold", action == "vende_miembro" and floor_unit),
    ):
        if hit:
            delta.add[stat] = 1
    if action == "gana_subasta" and amount:
        delta.peak["pisos_auction_max"] = amount
    if action == "junta_aprobada" and silent:
        delta.add["pisos_silence"] = 1
    if action == "reforma":
        delta.add["pisos_reform_spent"] = amount
        if reform:
            delta.add[f"{PISOS_REFORM_PREFIX}{reform}"] = 1
        if rehab:
            delta.add["pisos_rehab"] = 1
    if action in ("plantas", "habitaciones"):
        delta.add["pisos_split_spent"] = amount
        delta.peak["pisos_split_units"] = units
    if action == "firma_candidato":
        if tenant:
            delta.add[f"{PISOS_TENANT_PREFIX}{tenant}"] = 1
        if risk == "alto":
            delta.add["pisos_chose_risky"] = 1
        elif risk == "bajo":
            delta.add["pisos_chose_safe"] = 1
        if young:
            delta.add["pisos_young70"] = 1
    return delta


def housing_keys_stats(
    action: str, *, amount: int = 0, offer: str = "", fame: int = 0, term: int = 0
) -> StatDelta:
    """Estadísticas de recuperar un piso y de la duración del contrato (9.23.0).

    Args:
        action: `oferta` (un inquilino del catálogo dice que no), `llaves` (dice que sí),
            `contraoferta` (le pagas lo que pidió), `deja` (no se lo pagas), `trinchera`
            (se atrinchera), `miembro` (le compras las llaves a un miembro), `vende_llaves`
            (eres el miembro que las vende), `regatea` (contraofertas entre miembros),
            `no_renueva`, `necesidad`, `indemniza` (pagas la del art. 9.3) o `duracion`.
        amount: Lo pagado o cobrado.
        offer: La oferta hecha (`housing.KEYS_OFFERS`), con `oferta`, `llaves` y `trinchera`.
        fame: Tu fama de casero después de comprar unas llaves.
        term: La duración elegida, con `duracion`.
    """
    add: dict[str, int] = {}
    peak: dict[str, int] = {}
    if action in ("oferta", "llaves", "trinchera"):
        add["pisos_keys_offers"] = 1
        if offer == "buenas":
            add["pisos_keys_free_asks"] = 1
    if action == "oferta":
        add["pisos_keys_refused"] = 1
    elif action == "trinchera":
        add["pisos_keys_trench"] = 1
    elif action == "deja":
        add["pisos_keys_dropped"] = 1
    elif action in ("llaves", "contraoferta", "miembro"):
        add["pisos_keys_bought"] = 1
        if amount:
            add["pisos_keys_paid"] = amount
            peak["pisos_keys_max"] = amount
        peak["pisos_keys_fame"] = fame
        if action == "llaves" and offer == "buenas":
            add["pisos_keys_free"] = 1
        elif action == "llaves" and offer == "generosa":
            add["pisos_keys_generous"] = 1
        elif action == "contraoferta":
            add["pisos_keys_counter"] = 1
        elif action == "miembro":
            add["pisos_keys_member"] = 1
    elif action == "vende_llaves":
        add["pisos_keys_sold"] = 1
        if amount:
            add["pisos_keys_sold_amount"] = amount
    elif action == "regatea":
        add["pisos_keys_haggles"] = 1
    elif action == "no_renueva":
        add["pisos_no_renew"] = 1
    elif action == "necesidad":
        add["pisos_need"] = 1
    elif action == "indemniza":
        add["pisos_need_fine"] = 1
        add["pisos_need_fine_paid"] = amount
    elif action == "duracion":
        add["pisos_term_changes"] = 1
        add[f"{PISOS_TERM_PREFIX}{term}"] = 1
    return StatDelta(add=add, peak=peak)


def housing_day_stats(
    *,
    rent: int,
    ibi: int,
    events: tuple[str, ...],
    bono: int = 0,
    installments: int = 0,
    insurer: int = 0,
    bonus: int = 0,
    tenants: tuple[str, ...] = (),
    news: tuple[str, ...] = (),
    young: int = 0,
    moods: tuple[int, ...] = (),
    reviews: tuple[int, ...] = (),
) -> StatDelta:
    """Estadísticas de un día cerrado de los pisos de un miembro.

    Args:
        rent: Renta cobrada (antes del IRPF).
        ibi: IBI pagado.
        events: Lo que ha pasado en sus inmuebles o le ha pasado a él
            (`housing.Event.key`, `ejecucion`, `sorteo_vpo`, `cuota_impagada`, `noticia`…).
        bono: Bono Alquiler Joven cobrado.
        installments: Cuotas de hipoteca pagadas enteras.
        insurer: Lo que le ha pagado el seguro de impago.
        bonus: Lo que deduce por alquilar una vivienda vacía (art. 16).
        tenants: Inquilinos del catálogo que han firmado hoy en sus pisos.
        news: Noticias de barrio que salen hoy donde tiene pisos.
        young: Contratos de hoy con la reducción del 70 %.
        moods: Humor de sus inquilinos al cerrar el día.
        reviews: Estrellas de cada reseña que han dejado hoy en sus vacacionales.
    """
    add: dict[str, int] = {}
    peak: dict[str, int] = {}
    if reviews:
        add["pisos_reviews"] = len(reviews)
        if fives := sum(1 for s in reviews if s == 5):
            add["pisos_five_stars"] = fives
        if ones := sum(1 for s in reviews if s == 1):
            add["pisos_one_star"] = ones
    if moods:
        peak["pisos_mood_max"] = max(moods)
        if min(moods) <= 20:
            add["pisos_mood_low"] = 1
    if insurer > 0:
        add["pisos_insurer_paid"] = insurer
    if bonus > 0:
        add["pisos_vacant_bonus"] = 1
    if young > 0:
        add["pisos_young70"] = young
    for tenant in tenants:
        add[f"{PISOS_TENANT_PREFIX}{tenant}"] = 1
    for key in news:
        add[f"{PISOS_NEWS_PREFIX}{key}"] = 1
    if bono > 0:
        add["pisos_bono"] = bono
    if installments > 0:
        add["pisos_installments"] = installments
    if rent > 0:
        add["pisos_rent"] = rent
        add["pisos_rent_days"] = 1
    if ibi > 0:
        add["pisos_ibi"] = ibi
    for kind in events:
        stat = f"{PISOS_EVENT_PREFIX}{kind}"
        add[stat] = add.get(stat, 0) + 1
    return StatDelta(add=add, peak=peak)


def donation_stats(
    *,
    ong: str,
    amount: int,
    ongs_supported: int,
    balance_after: int,
    when: datetime,
    given: Mapping[str, int] | None = None,
    top_ong: bool = False,
    top_all: bool = False,
) -> StatDelta:
    """Estadísticas de un donativo a una ONG (`donar`).

    Args:
        ong: Clave de la ONG.
        amount: Lo donado.
        ongs_supported: ONGs distintas a las que ha donado el miembro.
        balance_after: Saldo tras donar (0 si lo ha dado todo).
        given: Lo donado a cada ONG desde siempre, ya con este donativo, para los niveles
            de mecenas. Sin él, no cuentan.
        top_ong: Si tras donar es quien más ha donado a esa ONG en el servidor.
        top_all: Si tras donar encabeza el muro de donantes (todas las ONGs).
    """
    delta = StatDelta(
        add={"donated": amount, "donations": 1, f"donated_{ong}": amount},
        peak={"ongs_supported": ongs_supported, "donation_max": amount},
    )
    exact = False
    if given:
        level = patron_level(given.get(ong, amount))
        if level is not None:
            delta.peak["patron_level_max"] = PATRON_LEVELS.index(level) + 1
        delta.peak["patron_ongs"] = sum(patron_level(v) is not None for v in given.values())
        gold = PATRON_LEVELS[2].threshold
        delta.peak["patron_gold_ongs"] = sum(v >= gold for v in given.values())
        before = given.get(ong, amount) - amount
        target = next_patron_level(before)
        exact = target is not None and amount == target.threshold - before
    for stat, hit in (
        ("donation_one", amount == 1),
        ("donation_allin", balance_after == 0),
        ("donation_666", amount == 666),
        ("donation_69", amount == 69),
        ("donation_420", amount == 420),
        ("donation_exact_level", exact),
        ("donation_christmas", when.month == 12 and when.day in (24, 25)),
        ("donation_dawn", when.hour < 6),
        ("donation_canarias", when.month == 5 and when.day == 30),
        # La última hora antes del sorteo de los viernes a las 20:00.
        ("donation_last_call", when.weekday() == 4 and when.hour == 19),
        # Los 14.999 € del contrato menor troceado y los 53 millones del rescate (a escala).
        ("donation_corona_minor", ong == "corona" and amount == 14_999),
        ("donation_friday13", when.weekday() == 4 and when.day == 13),
        ("donation_halloween", when.month == 10 and when.day == 31),
        ("donation_innocents", when.month == 12 and when.day == 28),
        ("donation_new_year", when.month == 12 and when.day == 31),
        ("donation_kings", when.month == 1 and when.day == 6),
        ("donation_pino", when.month == 9 and when.day == 8),
        ("donation_ticket_exact", amount == RAFFLE_MIN),
        ("donation_corona_rescue", ong == "corona" and amount == 5_300),
        ("donation_buitre_rent", ong == "buitre" and amount == 1_200),
        ("donation_gamers_1337", ong == "gamers" and amount == 1_337),
        ("donation_hambre_lunch", ong == "hambre" and 14 <= when.hour < 16),
        ("donation_top_ong", top_ong),
        ("donation_top_all", top_all),
    ):
        if hit:
            delta.add[stat] = 1
    return delta


def ong_raffle_stats(*, won: bool, entrants: int, tickets: int, rival_tickets: int) -> StatDelta:
    """Estadísticas de quien entra en el sorteo de una ONG.

    Args:
        won: Si lo ha ganado.
        entrants: Cuántos entraban en ese sorteo (él incluido).
        tickets: Sus boletos.
        rival_tickets: Los boletos del rival con más (0 si iba solo).
    """
    delta = StatDelta(add={"ong_raffle_entered": 1, "ong_raffle_lost": int(not won)})
    if won:
        delta.add["ong_raffle_won"] = 1
        if entrants == 1:
            delta.add["ong_raffle_alone"] = 1
        if tickets == 1 and rival_tickets >= 5:
            delta.add["ong_raffle_underdog"] = 1
    return delta


def ong_gift_stats(*, exclusive: bool, owned: Collection[str] = ()) -> StatDelta:
    """Estadísticas de un regalo de una ONG (por subir de nivel o en su sorteo).

    Args:
        owned: Claves de lo que tiene en la mochila tras recibirlo, para las colecciones
            de exclusivos (cuántos distintos y cuántos de la ONG de la que más tiene).
    """
    delta = StatDelta(add={"ong_gifts": 1, "ong_exclusive_gifts": int(exclusive)})
    per_ong = [len({g.catalog_key for g in gifts} & set(owned)) for gifts in GIFTS_BY_ONG.values()]
    if any(per_ong):
        delta.peak["ong_exclusives_owned"] = sum(per_ong)
        delta.peak["ong_exclusive_set_max"] = max(per_ong)
    return delta


def market_swap_stats(
    *, gave: int, got: int, money: int, proposer: bool, titles: bool, when: datetime
) -> StatDelta:
    """Estadísticas de un trueque, para cada una de las dos personas.

    Args:
        gave: Valor de referencia de lo que dio (más el dinero, si lo puso).
        got: Valor de referencia de lo que recibió (más el dinero, si lo cobró).
        money: Dinero que añadió quien propuso.
        proposer: Si es quien lo propuso.
        titles: Si se cambiaron dos títulos.
    """
    delta = StatDelta(add={"market_swaps": 1, **_sunday(when)})
    for stat, hit in (
        ("market_swap_money", int(proposer and money > 0)),
        ("market_swap_lopsided", int(got >= 1_000 and got >= 10 * max(1, gave))),
        ("market_swap_fleeced", int(gave >= 1_000 and gave >= 10 * max(1, got))),
        ("market_swap_titles", int(titles)),
    ):
        if hit:
            delta.add[stat] = hit
    return delta


def market_sale_stats(
    *, price: int, cost: int, gain_tax: int, bids: int, when: datetime
) -> StatDelta:
    """Estadísticas de quien vende en el Rastro (venta directa o subasta).

    Args:
        price: Precio cobrado.
        cost: Lo que le costó.
        gain_tax: IRPF de la plusvalía.
        bids: Pujas que recibió el puesto (0 en una venta directa).
    """
    delta = StatDelta(
        add={"market_sold": 1, "market_sold_y": price, **_sunday(when)},
        peak={"market_bids_on_mine_max": bids},
    )
    for stat, hit in (
        ("market_gain_tax", gain_tax),
        ("market_loss", int(price < cost)),
        ("market_gifts_given", int(price == 0)),
        ("market_sold_one", int(price == 1)),
        ("market_666", int(price == 666)),
    ):
        if hit:
            delta.add[stat] = hit
    return delta


def market_purchase_stats(
    *,
    price: int,
    itp: int,
    auction: bool,
    serial: int | None,
    title: bool,
    tapete: bool,
    balance_after: int,
    when: datetime,
) -> StatDelta:
    """Estadísticas de quien compra en el Rastro.

    Args:
        price: Precio pagado (sin el ITP).
        itp: ITP pagado.
        auction: Si lo ganó en una subasta.
        serial: Número de serie, si es de edición limitada.
        title: Si es un título.
        tapete: Si es un tapete.
        balance_after: Saldo tras pagar.
    """
    delta = StatDelta(
        add={"market_bought": 1, "market_spent": price + itp, **_sunday(when)},
        peak={"market_bought_max": price, "balance_max": balance_after},
    )
    for stat, hit in (
        ("market_itp", itp),
        ("market_gift_received", int(price == 0)),
        ("market_auction_won", int(auction)),
        ("market_serial_bought", int(serial is not None)),
        ("market_title_bought", int(title)),
        ("market_tapete_bought", int(tapete)),
        ("market_666", int(price == 666)),
    ):
        if hit:
            delta.add[stat] = hit
    return delta


# -- Loterías --------------------------------------------------------------------------

#: Etiquetas de un boleto premiado que cuentan para logros concretos.
LOTTERY_TAGS = frozenset({"reintegro", "pedrea", "gordo_navidad", "jackpot", "lotto4", "lotto5"})


def lottery_buy_stats(
    *,
    game: str,
    units: int,
    cost: int,
    owned_in_draw: int,
    balance_after: int,
    jackpot: int = 0,
    picks: Iterable[Sequence[int]] = (),
    when: datetime | None = None,
) -> StatDelta:
    """Estadísticas de una compra de décimos o apuestas.

    Args:
        game: Clave del juego (`bot.services.lottery.GAMES`).
        units: Décimos o apuestas comprados.
        cost: Lo pagado.
        owned_in_draw: Décimos o apuestas del miembro en ese sorteo tras comprar.
        balance_after: Saldo tras pagar.
        jackpot: Bote del sorteo al comprar (juegos de bote).
        picks: Los números de cada apuesta o el de cada décimo, para los números con guasa.
        when: Hora local de la compra (la racha de días y las fechas).
    """
    delta = StatDelta(
        add={"lottery_bets": units, "lottery_spent": cost},
        peak={"lottery_draw_bets_max": owned_in_draw},
    )
    per_game = {
        "navidad": "lottery_navidad",
        "nino": "lottery_nino",
        "euromillones": "lottery_euro_bets",
    }
    if game in per_game:
        delta.add[per_game[game]] = units
    delta.add[f"lottery_game_{game}"] = units
    if balance_after == 0:
        delta.add["lottery_broke_buy"] = 1
    lottery_game = LOTTERY_GAME_BY_KEY.get(game)
    if lottery_game is not None and lottery_game.categories:
        delta.peak["lottery_pool_bets_max"] = owned_in_draw
        if jackpot:
            delta.peak["lottery_jackpot_seen"] = jackpot
    for numbers in picks:
        if lottery_game is not None and lottery_game.categories:
            if tuple(numbers) == (1, 2, 3, 4, 5, 6):
                delta.add["lottery_123456"] = 1
            continue
        if len(numbers) != 1:
            continue
        number = f"{numbers[0]:05d}"
        if number == number[::-1]:
            delta.add["lottery_capicua"] = 1
        if number == "00000":
            delta.add["lottery_zeros"] = 1
        if number.endswith("666"):
            delta.add["lottery_666"] = 1
    if when is not None:
        delta.add[f"{LOTTERY_DAY_PREFIX}{when:%Y%m%d}"] = 1
        if game == "navidad" and (when.month, when.day) in ((12, 21), (12, 22)):
            delta.add["lottery_xmas_last"] = 1
    return delta


def lottery_prize_stats(prizes: Iterable[tuple[int, int, frozenset[str]]]) -> StatDelta:
    """Estadísticas de los boletos premiados de un miembro en un sorteo.

    Args:
        prizes: `(premio bruto, gravamen, etiquetas)` de cada boleto premiado.
            Las etiquetas salen de `LOTTERY_TAGS`.
    """
    delta = StatDelta()
    for gross, tax, tags in prizes:
        delta.merge(
            StatDelta(
                add={"lottery_prizes": 1, "lottery_won": gross},
                peak={"lottery_win_max": gross},
            )
        )
        for tag in tags & LOTTERY_TAGS:
            stat = "lottery_reintegros" if tag == "reintegro" else f"lottery_{tag}"
            delta.merge(StatDelta(add={stat: 1}))
        if tax:
            delta.merge(StatDelta(add={"lottery_gravamen": tax, "tax_paid": tax}))
    return delta


def scratch_stats(
    *,
    cost: int,
    prize: int,
    tax: int,
    top: bool,
    balance_after: int,
    near: bool = False,
    when: datetime | None = None,
) -> StatDelta:
    """Estadísticas de un rasca.

    Args:
        cost: Precio del rasca.
        prize: Premio bruto (0 si no toca).
        tax: Gravamen especial pagado.
        top: Si es el premio más alto de su tabla.
        balance_after: Saldo tras cobrar el premio.
        near: Si, sin premio, enseñaba dos casillas del premio más alto.
        when: Hora local (la racha de días y las fechas).
    """
    delta = StatDelta(add={"lottery_scratches": 1, "lottery_spent": cost})
    if balance_after == 0:
        delta.add["lottery_broke_buy"] = 1
    if prize:
        delta.merge(lottery_prize_stats([(prize, tax, frozenset())]))
    if top:
        delta.add["lottery_scratch_top"] = 1
    if near:
        delta.add["lottery_scratch_near"] = 1
    if when is not None:
        delta.add[f"{LOTTERY_DAY_PREFIX}{when:%Y%m%d}"] = 1
        if 2 <= when.hour < 6:
            delta.add["lottery_scratch_night"] = 1
        if when.weekday() == 4 and when.day == 13:
            delta.add["lottery_scratch_friday13"] = 1
    return delta


def lottery_check_stats(*, when: datetime) -> StatDelta:
    """Comprobar el último boleto sorteado en 🎟️ Mis boletos: cuenta una vez al día.

    Args:
        when: Hora local.
    """
    return StatDelta(peak={f"{LOTTERY_CHECK_DAY_PREFIX}{when:%Y%m%d}": 1})


